1	import { db } from "../lib/db";
2	import { pve, node, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
3	import { writeFile, unlink } from "node:fs/promises";
4	import { ovhConfigured } from "../lib/ovh";
5	import { allocateDedicatedIp, releaseDedicatedIp, syncDedicatedIpPool } from "../lib/dedicated-ip";
6	import { allocateIp, allocateSshPort, gatewayIp } from "../lib/ipam";
7	import { syncPortForwards } from "./network";
8	import { billingSweep } from "./billing";
9	import { gameUpdate, gameUpdateSweep } from "./game-update";
10	import { backupRestore } from "./restore";
11	import { claudeBuild } from "./claude";
12	import { geoEnrichSweep } from "./geo";
13	import { monitorSweep } from "./monitor";
14	import { scheduledBackupSweep } from "./backup-schedule";
15	import { volumeCreate, volumeAttach, volumeDetach, volumeDelete } from "./volumes";
16	import { randomBytes } from "node:crypto";
17	import type { Job, Server } from "@prisma/client";
