19	const POLL_MS = 3000;
20	const MAX_ATTEMPTS = 3;
21	
22	function generatePassword(): string {
23	  // URL-safe, no ambiguous chars, 16 chars
24	  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
25	}
