27	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
28	  const server = await db.server.findUnique({
29	    where: { id: job.serverId! },
30	    include: { plan: true, osTemplate: true, node: true },
31	  });
32	  if (!server) throw new Error(`Server ${job.serverId} not found`);
33	  return server as any;
34	}
