36	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
37	async function nodeFor(server: any) {
38	  const n =
39	    server.node ??
40	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
41	    (await db.node.findFirst({ where: { enabled: true } }));
42	  if (!n) {
43	    // No Node rows yet — use the env-configured primary via the global client.
44	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
45	  }
46	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
47	}
