49	/** YAML-safe indent of a multi-line script under a `content: |` block. */
50	function indentBlock(text: string, spaces: number): string {
51	  const pad = " ".repeat(spaces);
52	  return text.split("\n").map((l) => pad + l).join("\n");
53	}
