190	async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
191	  const server = await loadServer(job);
192	  const { conn } = await nodeFor(server);
193	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
194	  await conn.waitForTask(upid);
195	  await db.server.update({
196	    where: { id: server.id },
197	    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
198	  });
199	}
