201	async function destroyVm(conn: any, vmid: number) {
202	  // Stop first (ignore failure if already stopped), then destroy
203	  try {
204	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
205	    await conn.waitForTask(stopUpid);
206	  } catch {
207	    /* already stopped or does not exist */
208	  }
209	  const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${vmid}`, {
210	    "destroy-unreferenced-disks": 1,
211	    purge: 1,
212	  });
213	  await conn.waitForTask(delUpid, 600_000);
214	}
