216	async function remove(job: Job) {
217	  const server = await loadServer(job);
218	  const { conn } = await nodeFor(server);
219	  if (server.vmid) {
220	    try {
221	      await destroyVm(conn, server.vmid);
222	    } catch (e: any) {
223	      // VM may never have been created; only swallow "does not exist"
224	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
225	    }
226	    // Best-effort: remove the per-server cloud-init snippet
227	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
228	  }
229	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC)
230	  await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
231	  await db.server.delete({ where: { id: server.id } });
232	  await syncPortForwards();
233	}
