235	async function reinstall(job: Job) {
236	  const server = await loadServer(job);
237	  const { conn } = await nodeFor(server);
238	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
239	  if (server.vmid) await destroyVm(conn, server.vmid);
240	  await provision(job);
241	}
