300	async function resize(job: Job) {
301	  const server = await loadServer(job);
302	  const payload = (job.payload ?? {}) as { planId?: string };
303	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
304	  if (!newPlan) throw new Error("resize: target plan not found");
305	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
306	
307	  const { conn } = await nodeFor(server);
308	  const wasRunning = server.status === "RUNNING";
309	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
310	    cores: newPlan.cpuCores,
311	    memory: newPlan.ramMB,
312	  });
313	  if (newPlan.diskGB > server.plan.diskGB) {
314	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
315	      disk: "scsi0",
316	      size: `${newPlan.diskGB}G`,
317	    });
318	  }
319	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
320	  // CPU/RAM changes need a power cycle to apply
321	  if (wasRunning) {
322	    try {
323	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
324	      await conn.waitForTask(stopUpid, 120_000);
325	    } catch {
326	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
327	      await conn.waitForTask(stopUpid);
328	    }
329	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
330	    await conn.waitForTask(startUpid);
331	  }
332	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
333	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${newPlan.diskGB} GB disk`,
334	    `/dashboard/servers/${server.id}`);
335	}
