337	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
338	  const server = await loadServer(job);
339	  const payload = (job.payload ?? {}) as { name?: string };
340	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
341	  if (!name) throw new Error("snapshot: invalid name");
342	  const { conn } = await nodeFor(server);
343	  let upid: string;
344	  if (op === "create") {
345	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
346	  } else if (op === "delete") {
347	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
348	  } else {
349	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
350	  }
351	  await conn.waitForTask(upid, 600_000);
352	  if (op === "rollback") {
353	    // rollback leaves the VM stopped; bring it back if the server should be running
354	    const current = await db.server.findUnique({ where: { id: server.id } });
355	    if (current?.status === "RUNNING") {
356	      try {
357	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
358	        await conn.waitForTask(startUpid);
359	      } catch { /* may already be running */ }
360	    }
361	  }
362	}
