401	async function backupCreate(job: Job) {
402	  const server = await loadServer(job);
403	  const { conn } = await nodeFor(server);
404	  const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
405	    vmid: server.vmid,
406	    storage: "backup",
407	    mode: "snapshot",
408	    compress: "zstd",
409	  });
410	  await conn.waitForTask(upid, 3_600_000);
411	  await notify(server.userId, `Backup completed for ${server.hostname}`, undefined,
412	    `/dashboard/servers/${server.id}`);
413	}
