415	const handlers: Record<string, (job: Job) => Promise<void>> = {
416	  PROVISION: provision,
417	  START: (j) => powerAction(j, "start"),
418	  STOP: (j) => powerAction(j, "stop"),
419	  REBOOT: (j) => powerAction(j, "reboot"),
420	  DELETE: remove,
421	  REINSTALL: reinstall,
422	  SUSPEND: (j) => suspend(j, false),
423	  UNSUSPEND: (j) => suspend(j, true),
424	  RESIZE: resize,
425	  SNAPSHOT_CREATE: (j) => snapshotOp(j, "create"),
426	  SNAPSHOT_DELETE: (j) => snapshotOp(j, "delete"),
427	  SNAPSHOT_ROLLBACK: (j) => snapshotOp(j, "rollback"),
428	  BACKUP_CREATE: backupCreate,
429	  BACKUP_RESTORE: backupRestore,
430	  PASSWORD_RESET: passwordReset,
431	  SYNC_FORWARDS: async () => syncPortForwards(),
432	  GAME_UPDATE: gameUpdate,
433	  CLAUDE_BUILD: claudeBuild,
434	  VOLUME_CREATE: volumeCreate,
435	  VOLUME_ATTACH: volumeAttach,
436	  VOLUME_DETACH: volumeDetach,
437	  VOLUME_DELETE: volumeDelete,
438	};
