468	/**
469	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
470	 * killed worker leaves a job RUNNING forever, which permanently blocks the
471	 * server's "one in-flight job" guard and strands it in a transitional state.
472	 */
473	async function reapStuckJobs() {
474	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
475	  for (const job of stuck) {
476	    const retriable = job.attempts < MAX_ATTEMPTS;
477	    await db.job.update({
478	      where: { id: job.id },
479	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
480	    });
481	    if (!retriable && job.serverId) {
482	      const s = await db.server.findUnique({ where: { id: job.serverId } });
483	      if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
484	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
485	      }
486	    }
