17	/**
18	 * Pull additional/failover IPv4 addresses routed to our server from OVH and
19	 * upsert them into the pool. The host's own primary IP is never poolable.
20	 */
21	export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
22	  if (!ovhConfigured()) return { imported: 0, total: 0 };
23	  const primary = process.env.PUBLIC_IP;
24	  const blocks: string[] = await ovhApi.ips();
25	  let imported = 0;
26	  for (const block of blocks) {
27	    if (block.includes(":")) continue; // IPv6 handled separately
28	    let info: any;
29	    try {
30	      info = await ovhApi.ipInfo(block);
31	    } catch {
32	      continue;
33	    }
34	    if (info?.routedTo?.serviceName !== SERVER) continue;
35	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
36	    // A /32 block is a single usable IP == the block minus the mask.
37	    const address = block.split("/")[0];
38	    if (address === primary) continue;
39	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
40	    if (!existing) {
41	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE" } });
42	      imported++;
43	    }
44	  }
45	  const total = await db.dedicatedIp.count();
46	  return { imported, total };
47	}
