15	async function pveRequestTo(
16	  base: string,
17	  token: string,
18	  method: "GET" | "POST" | "PUT" | "DELETE",
19	  path: string,
20	  params?: Record<string, string | number | undefined>
21	): Promise<any> {
22	  const url = new URL(`${base}/api2/json${path}`);
23	  let body: string | undefined;
24	  const headers: Record<string, string> = { Authorization: token };
25	
26	  const clean = Object.fromEntries(
27	    Object.entries(params ?? {}).filter(([, v]) => v !== undefined)
28	  ) as Record<string, string>;
29	
30	  if (method === "GET" || method === "DELETE") {
31	    for (const [k, v] of Object.entries(clean)) url.searchParams.set(k, String(v));
32	  } else {
33	    body = new URLSearchParams(clean as Record<string, string>).toString();
34	    headers["Content-Type"] = "application/x-www-form-urlencoded";
35	  }
36	
37	  const res = await undiciFetch(url, { method, headers, body, dispatcher: insecureAgent });
38	  const text = await res.text();
39	  if (!res.ok) {
40	    throw new ProxmoxError(`PVE ${method} ${path} -> ${res.status}`, res.status, text);
41	  }
42	  try {
43	    return JSON.parse(text).data;
44	  } catch {
45	    return text;
46	  }
47	}
48	
49	function pveRequest(
50	  method: "GET" | "POST" | "PUT" | "DELETE",
51	  path: string,
52	  params?: Record<string, string | number | undefined>
53	) {
54	  return pveRequestTo(BASE, TOKEN, method, path, params);
55	}
