38	    server?.node ??
39	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
40	    (await db.node.findFirst({ where: { enabled: true } }));
41	  if (!n) {
42	    return {
43	      conn: {
44	        get: pve.get,
45	        post: pve.post,
46	        put: pve.put,
47	        del: pve.del,
48	        node: envNode,
49	        waitForTask,
50	        nextVmid,
51	        vmStatus,
52	      } as any,
53	      row: null,
54	    };
55	  }
56	  return {
57	    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
58	    row: n,
59	  };
60	}
