120	// ---------- 3. Resize-down ----------
121	
122	/**
123	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
124	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
125	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
126	 * otherwise). A prorated credit for the price difference over the remaining term
127	 * is returned to the wallet.
128	 */
129	export async function resizeServerDown(
130	  serverId: string,
131	  newPlanId: string
132	): Promise<{ error?: string }> {
133	  const { user, server } = await ownedServer(serverId);
134	
135	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
136	  if (!newPlan?.active) return { error: "Plan not available." };
137	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
138	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
139	
140	  // This action is downgrades only — upgrades go through resizeServer().
141	  if (newPlan.priceCents >= server.plan.priceCents) {
142	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
143	  }
144	  // Disk can't shrink destructively; block the move rather than lose data.
145	  if (newPlan.diskGB < server.plan.diskGB) {
146	    return {
147	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
148	    };
149	  }
150	
151	  if (await hasInflightJob(serverId)) {
152	    return { error: "Another operation is already in progress on this server." };
153	  }
154	
155	  // Prorated credit: refund the price difference for the unused portion of the
156	  // current billing term (paid servers only; free servers get nothing to refund).
157	  let creditCents = 0;
158	  if (!server.isFree && server.expiresAt) {
159	    const now = Date.now();
160	    const periodStart = addMonths(server.expiresAt, -server.termMonths).getTime();
161	    const periodMs = server.expiresAt.getTime() - periodStart;
162	    const remainingFraction =
163	      periodMs > 0
164	        ? Math.max(0, Math.min(1, (server.expiresAt.getTime() - now) / periodMs))
165	        : 0;
166	    const deltaFullTerm =
167	      vpsTermPriceCents(server.plan.priceCents, server.termMonths) -
168	      vpsTermPriceCents(newPlan.priceCents, server.termMonths);
169	    creditCents = Math.max(0, Math.round(deltaFullTerm * remainingFraction));
170	  }
171	
172	  await db.$transaction([
173	    ...(creditCents > 0
174	      ? [
175	          db.user.update({
176	            where: { id: server.userId },
177	            data: { balanceCents: { increment: creditCents } },
178	          }),
179	          db.walletTransaction.create({
180	            data: {
181	              userId: server.userId,
182	              amountCents: creditCents,
183	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
184	            },
185	          }),
186	        ]
187	      : []),
188	    db.job.create({ data: { type: "RESIZE", serverId, payload: { planId: newPlan.id } as any } }),
189	    db.auditLog.create({
190	      data: {
191	        userId: user.id,
192	        action: "server.resize_down",
193	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
194	      },
195	    }),
196	  ]);
197	
198	  revalidatePath(`/dashboard/servers/${serverId}`);
199	  return {};
200	}
