66	 * command over the private network, so the VM must be running.
67	 */
68	export async function triggerGameUpdate(serverId: string): Promise<{ error?: string }> {
69	  const { user, server } = await ownedServer(serverId);
70	  if (!isGameServer(server)) return { error: "Updates are only available for game servers." };
71	  if (server.status !== "RUNNING") {
