88	// ---------- Self-service backup restore ----------
89	
90	export type ServerBackup = { volid: string; ctime?: number; size?: number };
91	
92	/**
93	 * List the vzdump backups on the `backup` storage that belong to this server's
94	 * VMID. Read-only Proxmox call, ownership-checked.
95	 */
96	export async function listServerBackups(
97	  serverId: string
98	): Promise<{ error?: string; backups?: ServerBackup[] }> {
99	  const { server } = await ownedServer(serverId);
100	  if (!server.vmid) return { backups: [] };
101	  try {
102	    const backups = (await listBackups(server.vmid)) as ServerBackup[];
103	    backups.sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
104	    return { backups };
105	  } catch {
106	    return { error: "Could not reach the hypervisor — try again in a moment." };
107	  }
108	}
109	
110	/**
111	 * Enqueue a BACKUP_RESTORE job for the selected vzdump archive. This OVERWRITES
112	 * the server's current disk. The volid is validated against the server's own
113	 * backups so a customer can only restore their own VM's archives.
114	 */
115	export async function requestRestore(
116	  serverId: string,
117	  volid: string
118	): Promise<{ error?: string }> {
119	  const { user, server } = await ownedServer(serverId);
120	  if (!server.vmid) return { error: "Server has no VM yet." };
121	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
122	    return { error: "Server must be running or stopped to restore a backup." };
123	  }
124	
125	  // Validate the archive actually belongs to this server's VMID (prevents
126	  // restoring another customer's backup by guessing a volid).
127	  let owned: ServerBackup[];
128	  try {
129	    owned = (await listBackups(server.vmid)) as ServerBackup[];
130	  } catch {
131	    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
132	  }
133	  if (!owned.some((b) => b.volid === volid)) {
134	    return { error: "That backup was not found for this server." };
135	  }
136	
137	  const idle = await ensureIdle(serverId);
138	  if (idle.error) return idle;
139	
140	  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
141	  await db.auditLog.create({
142	    data: { userId: user.id, action: "server.backup_restore", detail: `${serverId} ${volid}` },
143	  });
144	  revalidatePath(`/dashboard/servers/${serverId}`);
145	  return {};
146	}
