1	import { db } from "./db";
2	import { pveFor } from "./proxmox";
3	
4	/**
5	 * Host capacity accounting for the deploy flow.
6	 *
7	 * We oversell RAM (the scarce resource) by a factor, but never past the
8	 * host's physical RAM minus a reserve for the hypervisor itself. Disk on
9	 * `vmdata` is large relative to plan sizes, so RAM is the binding constraint.
10	 *
11	 * All values are overridable via env so staging/prod can differ without code
12	 * changes; the defaults match the production KS-GAME box (64 GB RAM).
13	 */
14	export const HOST_RAM_MB = Number(process.env.NXEON_HOST_RAM_MB ?? 64000);
15	export const HOST_RAM_RESERVE_MB = Number(process.env.NXEON_HOST_RAM_RESERVE_MB ?? 8000);
16	export const RAM_OVERSELL_FACTOR = Number(process.env.NXEON_RAM_OVERSELL ?? 1.5);
17	
18	/**
19	 * Usable NVMe VM-disk pool in GB, used as a fallback when the live Proxmox
20	 * storage total can't be read. Unlike RAM we do NOT oversell disk — thin
21	 * provisioning already lets guests share the pool, so we commit against the
22	 * real pool size minus a safety margin.
23	 */
24	export const HOST_DISK_GB = Number(process.env.NXEON_HOST_DISK_GB ?? 800);
25	/** Fraction of usable disk we allow to be committed before refusing deploys. */
26	export const DISK_SAFETY_RATIO = Number(process.env.NXEON_DISK_SAFETY ?? 0.9);
27	
28	/** Effective committable RAM ceiling in MB after reserve + oversell. */
29	export function ramCeilingMB(): number {
30	  return Math.max(0, (HOST_RAM_MB - HOST_RAM_RESERVE_MB) * RAM_OVERSELL_FACTOR);
31	}
32	
33	export type CapacitySnapshot = {
34	  committedRamMB: number;
35	  committedDiskGB: number;
36	  ceilingRamMB: number;
37	  serverCount: number;
38	  /** 0..1 fraction of the RAM ceiling already committed. */
39	  ramUtilization: number;
40	  /** true once committed RAM is within 15% of the ceiling. */
41	  nearCapacity: boolean;
42	};
43	
44	/** Sum committed RAM/disk across all servers that are not being torn down. */
45	export async function capacitySnapshot(): Promise<CapacitySnapshot> {
46	  const servers = await db.server.findMany({
47	    where: { status: { not: "DELETING" } },
48	    select: { plan: { select: { ramMB: true, diskGB: true } } },
49	  });
50	  const committedRamMB = servers.reduce((sum, s) => sum + s.plan.ramMB, 0);
51	  const committedDiskGB = servers.reduce((sum, s) => sum + s.plan.diskGB, 0);
52	  const ceilingRamMB = ramCeilingMB();
53	  const ramUtilization = ceilingRamMB > 0 ? committedRamMB / ceilingRamMB : 1;
54	  return {
55	    committedRamMB,
56	    committedDiskGB,
57	    ceilingRamMB,
58	    serverCount: servers.length,
59	    ramUtilization,
60	    nearCapacity: ramUtilization >= 0.85,
61	  };
62	}
63	
64	/**
65	 * Would deploying `planId` push committed RAM past the oversell ceiling?
66	 * Returns { ok:false, reason } when the host cannot take the new server.
67	 */
68	export async function capacityCheck(planId: string): Promise<{ ok: boolean; reason?: string }> {
69	  const plan = await db.plan.findUnique({ where: { id: planId }, select: { ramMB: true, name: true } });
70	  if (!plan) return { ok: false, reason: "Plan not found." };
71	
72	  const snap = await capacitySnapshot();
73	  const projected = snap.committedRamMB + plan.ramMB;
74	  if (projected > snap.ceilingRamMB) {
75	    return {
76	      ok: false,
77	      reason:
78	        "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
79	        "Please try a smaller plan or contact support.",
80	    };
81	  }
82	  return { ok: true };
83	}
84	
85	/**
86	 * Would committing `addDiskGB` more of VM disk overflow the node's usable
87	 * storage? Mirrors `capacityCheck` but for disk: sums committed plan disk on
88	 * the node and compares against the usable NVMe pool times a safety ratio.
89	 *
90	 * Usable pool size is read live from Proxmox (`storageNvme` status) when the
91	 * node is reachable, falling back to `HOST_DISK_GB`. Pass `nodeId = null` to
92	 * check against all non-deleting servers / the primary node.
93	 */
94	export async function diskCapacityCheck(
95	  nodeId: string | null | undefined,
96	  addDiskGB: number
97	): Promise<{ ok: boolean; reason?: string }> {
98	  const servers = await db.server.findMany({
99	    where: { status: { not: "DELETING" }, ...(nodeId ? { nodeId } : {}) },
100	    select: { plan: { select: { diskGB: true } } },
101	  });
102	  const committedDiskGB = servers.reduce((sum, s) => sum + s.plan.diskGB, 0);
103	
104	  // Resolve usable pool size — prefer the live Proxmox NVMe pool total.
105	  let usableGB = HOST_DISK_GB;
106	  try {
107	    const n = nodeId
108	      ? await db.node.findUnique({ where: { id: nodeId } })
109	      : await db.node.findFirst({ where: { isPrimary: true } });
110	    if (n) {
111	      const client = pveFor({
112	        apiUrl: n.apiUrl,
113	        pveNode: n.pveNode,
114	        tokenId: n.tokenId,
115	        tokenSecret: n.tokenSecret,
116	      });
117	      const st = await client.get(`/nodes/${n.pveNode}/storage/${n.storageNvme}/status`);
118	      const totalGB = Number(st?.total ?? 0) / 1024 ** 3;
119	      if (totalGB > 0) usableGB = totalGB;
120	    }
121	  } catch {
122	    // Proxmox unreachable — fall back to the configured HOST_DISK_GB.
123	  }
124	
125	  const ceilingGB = usableGB * DISK_SAFETY_RATIO;
126	  const projected = committedDiskGB + addDiskGB;
127	  if (projected > ceilingGB) {
128	    return {
129	      ok: false,
130	      reason:
131	        "Not enough disk headroom on this node to deploy this plan right now. " +
132	        "Please choose a smaller disk or contact support.",
133	    };
134	  }
135	  return { ok: true };
136	}
