72	// ---- Convenience wrappers for dedicated IPs / Virtual MACs / reverse DNS ----
73	
74	export const ovhApi = {
75	  me: () => ovh("GET", "/me"),
76	  servers: () => ovh("GET", "/dedicated/server") as Promise<string[]>,
77	  server: (name: string) => ovh("GET", `/dedicated/server/${name}`),
78	  ips: () => ovh("GET", "/ip") as Promise<string[]>,
79	  ipInfo: (ip: string) => ovh("GET", `/ip/${encodeURIComponent(ip)}`),
80	  /** Virtual MACs registered on a dedicated server. */
81	  virtualMacs: (server: string) => ovh("GET", `/dedicated/server/${server}/virtualMac`),
82	  /** Create a Virtual MAC for an additional IP so it can be routed to a VM. */
83	  createVirtualMac: (server: string, ipAddress: string, name: string) =>
84	    ovh("POST", `/dedicated/server/${server}/virtualMac`, {
