86	      type: "ovh",
87	      virtualMachineName: name,
88	    }),
89	  /** Set reverse DNS (PTR) for an IP. */
90	  setReverse: (ipBlock: string, ip: string, reverse: string) =>
91	    ovh("POST", `/ip/${encodeURIComponent(ipBlock)}/reverse`, { ipReverse: ip, reverse }),
92	};
