55	export async function backupRestore(job: Job): Promise<void> {
56	  const server = await loadServer(job.serverId!);
57	  if (!server.vmid) throw new Error("restore: server has no VM");
58	
59	  const payload = (job.payload ?? {}) as { volid?: string };
60	  const volid = payload.volid;
61	  if (!volid) throw new Error("restore: missing volid");
62	
63	  const conn = await nodeFor(server);
64	  const vmid = server.vmid;
65	  const wasRunning = server.status === "RUNNING";
66	
67	  // 1) Stop the VM so the disk can be overwritten (ignore "already stopped").
68	  try {
69	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
70	    await conn.waitForTask(stopUpid);
71	  } catch {
72	    /* already stopped / not running */
73	  }
74	  await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });
75	
76	  // 2) Restore the archive over the existing VMID (force overwrite). Storage is
77	  //    left to the archive's recorded config so disks land where they were.
78	  const restoreUpid = await conn.post(`/nodes/${conn.node}/qemu`, {
79	    vmid,
80	    archive: volid,
81	    force: 1,
82	  });
83	  await conn.waitForTask(restoreUpid, 3_600_000);
84	
85	  // 3) Bring the VM back up if it was running before the restore.
86	  if (wasRunning) {
87	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
88	    await conn.waitForTask(startUpid);
89	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
90	  }
91	
92	  await notify(
93	    server.userId,
94	    `Backup restored on ${server.hostname}`,
95	    "Your server was restored from the selected backup. Any changes made after that backup are gone.",
96	    `/dashboard/servers/${server.id}`
97	  );
98	}
