9	/**
10	 * Game-server auto-update handlers.
11	 *
12	 * `gameUpdate` runs a best-effort, per-family update command over SSH against
13	 * the server's private IP (the worker can reach vmbr1). `gameUpdateSweep` finds
14	 * RUNNING game servers with `autoUpdate=true` and enqueues GAME_UPDATE jobs for
15	 * them — safe to call periodically (it de-dupes on in-flight jobs).
16	 *
17	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
18	 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
19	 */
20	
21	/** Steam dedicated-server app IDs for steamcmd-based families. */
22	const STEAM_APPID: Partial<Record<GameFamily, string>> = {
23	  valheim: "896660",
24	  rust: "258550",
25	  palworld: "2394010",
26	  cs2: "730",
27	};
28	
29	/** systemd service name candidates per family (first that exists wins). */
30	const SERVICE_HINT: Record<GameFamily, string> = {
31	  minecraft: "minecraft",
32	  valheim: "valheim",
33	  rust: "rust",
34	  palworld: "palworld",
35	  cs2: "cs2",
36	  terraria: "terraria",
37	};
