39	/**
40	 * Build a best-effort remote update command. For steamcmd-based games we run an
41	 * anonymous `app_update ... validate` if steamcmd is present, then (always)
42	 * restart the matching systemd service. Everything is tolerant (`|| true`) so a
43	 * missing tool/service never fails the whole job for an otherwise-healthy VM.
44	 */
45	function updateCommand(family: GameFamily): string {
46	  const appId = STEAM_APPID[family];
47	  const svc = SERVICE_HINT[family];
48	  const steam = appId
49	    ? `if command -v steamcmd >/dev/null 2>&1; then steamcmd +login anonymous +app_update ${appId} validate +quit || true; fi; `
50	    : "";
51	  // Restart the named service, then a "<family>-server" variant, then any unit
52	  // whose name contains the family; never hard-fail.
53	  const restart =
54	    `systemctl restart ${svc} 2>/dev/null || ` +
55	    `systemctl restart ${svc}-server 2>/dev/null || ` +
56	    `svc=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}'); ` +
57	    `if [ -n "$svc" ]; then systemctl restart "$svc" || true; fi`;
58	  return `set -e; ${steam}${restart}; true`;
59	}
