15	/**
16	 * Subscription sweep, run periodically by the worker:
17	 *  - expired + autoRenew + sufficient balance  -> charge wallet, extend 30 days
18	 *  - expired beyond grace (or autoRenew off)   -> queue SUSPEND with unpaid note
19	 * Free servers (isFree) are never touched.
20	 */
21	export async function billingSweep() {
22	  const now = new Date();
23	
24	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
25	  const soon = new Date(now.getTime() + 3 * 86400_000);
26	  const upcoming = await db.server.findMany({
27	    where: {
28	      isFree: false,
29	      expiresAt: { gt: now, lt: soon },
30	      status: { in: ["RUNNING", "STOPPED"] },
31	    },
32	    include: { plan: true, user: true, gamePlan: true },
33	  });
34	  for (const server of upcoming) {
35	    const warnCents = server.gamePlan ? server.gamePlan.priceCents : vpsTermPriceCents(server.plan.priceCents, server.termMonths);
36	    if (server.autoRenew && server.user.balanceCents >= warnCents) continue;
37	    const already = await db.notification.findFirst({
38	      where: {
39	        userId: server.userId,
40	        title: { contains: server.hostname },
41	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
42	        AND: { title: { contains: "renews soon" } },
43	      },
44	    });
45	    if (!already) {
46	      await db.notification.create({
47	        data: {
48	          userId: server.userId,
49	          title: `${server.hostname} renews soon — action needed`,
50	          body: server.autoRenew
51	            ? `Renewal is $${(server.plan.priceCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
52	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
53	          href: `/dashboard/servers/${server.id}`,
54	        },
55	      });
56	    }
57	  }
58	  const due = await db.server.findMany({
59	    where: {
60	      isFree: false,
61	      expiresAt: { lt: now },
62	      status: { in: ["RUNNING", "STOPPED"] },
63	    },
64	    include: { plan: true, user: true, gamePlan: true },
65	  });
66	
67	  for (const server of due) {
68	    const graceEnd = new Date(server.expiresAt!.getTime() + GRACE_DAYS * 86400_000);
69	    const renewTerm = vpsTerm(server.termMonths);
70	    const isGame = !!server.gamePlan;
71	    const renewMonths = isGame ? server.gamePlan!.termMonths : renewTerm.months;
72	    const renewCents = isGame
