export async function deleteMyAccount(confirmEmail: string): Promise<{ error?: string }> {
  const user = await requireUser();

  const typed = (confirmEmail ?? "").trim().toLowerCase();
  if (!typed) return { error: "Type your email to confirm." };
  if (typed !== user.email.toLowerCase()) {
    return { error: "That email doesn't match your account." };
  }

  const active = await activeServerCount(user.id);
  if (active > 0) {
    return {
      error: `You still have ${active} active server${active === 1 ? "" : "s"}. Delete ${
        active === 1 ? "it" : "them"
      } first, then close your account.`,
    };
  }

  await db.$transaction([
    // Record the deletion with no owning user (survives the cascade).
    db.auditLog.create({
      data: {
        userId: null,
        action: "user.account_deleted",
        detail: `${user.email} (${user.id}) — self-service GDPR deletion`,
      },
    }),
    // AuditLog.user has no cascade: anonymize this user's remaining trail.
    db.auditLog.updateMany({ where: { userId: user.id }, data: { userId: null } }),
    // Self-relation has no cascade: detach anyone this user referred.
    db.user.updateMany({ where: { referredById: user.id }, data: { referredById: null } }),
    // WalletTransaction.user has no cascade.
    db.walletTransaction.deleteMany({ where: { userId: user.id } }),
    // Server.user has no cascade. Past the guard only DELETING rows remain;
    // removing them cascades jobs, port forwards, dedicated IPs, claude builds, etc.
    db.server.deleteMany({ where: { userId: user.id } }),
    // PasswordResetToken has no FK relation — hygiene only.
    db.passwordResetToken.deleteMany({ where: { userId: user.id } }),
    // Cascades: projects, ssh keys, tickets, notifications, domains, invoices,
    // api tokens, memberships, owned orgs, coupon redemptions; feedback & gift
    // codes are set-null by the schema.
    db.user.delete({ where: { id: user.id } }),
  ]);

  await destroySession();
  redirect("/");
}
