47	  subnetPrefix: ENV_SUBNET_PREFIX,
48	  ipStart: IP_START,
49	  ipEnd: IP_END,
50	  sshPortStart: SSH_PORT_START,
51	  sshPortEnd: SSH_PORT_END,
52	  bridge: process.env.NXEON_BRIDGE ?? null,
